const body = $input.first().json.body ?? $input.first().json;
const d = body.data ?? body;
const { release, artist, mission, workflow, metadata, priority, context } = d;
if (!mission?.id || !release?.id) {
  throw new Error('Missing required fields: mission.id, release.id');
}
return [{ json: { release, artist, mission, workflow, metadata, priority, context, mission_id: mission.id } }];

const input = $input.first().json;
const executionId = `exec_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
return [{ json: { ...input, execution_id: executionId, status: 'accepted', estimated_duration_ms: 60000, workflow_version: 'v1' } }];

// ─────────────────────────────────────────────────────────────────────────
// CONTENT GENERATION — connect real credentials here:
//   ANTHROPIC_API_KEY (n8n-side) for AI-generated captions/hooks/hashtags
//   INSTAGRAM_ACCESS_TOKEN / TIKTOK_ACCESS_TOKEN / YOUTUBE credentials for
//   the posting schedule this calendar feeds into the Publishing Engine.
// The backend has already seeded 3 real content_ideas rows for this release
// via contentVaultService (see release-intel.service.ts::createDownstreamMissions);
// this workflow expands that into a full calendar once credentials exist.
// ─────────────────────────────────────────────────────────────────────────
const input = $input.first().json;
const missing = [];
if (!$env.ANTHROPIC_API_KEY) missing.push('ANTHROPIC_API_KEY');
if (!$env.INSTAGRAM_ACCESS_TOKEN) missing.push('INSTAGRAM_ACCESS_TOKEN');
if (!$env.TIKTOK_ACCESS_TOKEN) missing.push('TIKTOK_ACCESS_TOKEN');

return [{ json: {
  mission_id: input.mission_id,
  execution_id: input.execution_id,
  status: missing.length ? 'partial' : 'completed',
  summary: missing.length ? `Content Intelligence ready — waiting on: ${missing.join(', ')}` : 'Content calendar generation complete',
  results: {
    content_ideas: null,
    release_calendar: null,
    posting_schedule: null,
    captions: null,
    hooks: null,
    hashtags: null,
    campaign_timeline: null,
    missing_credentials: missing,
  },
} }];
